<?php
namespace App\Services\Marketing;
use App\Models\{MarketingPost,MarketingPostDispatch,MarketingChannelConnection,User,ProductImage};
use App\Jobs\PublishMarketingPost;
use App\Domain\Marketing\MarketingPermission;
use Illuminate\Support\Facades\{DB,Queue};
use Illuminate\Validation\ValidationException;
use Carbon\CarbonImmutable;
final class MarketingPostQueue {
 private function invalid(string $message):never{throw ValidationException::withMessages(['publishing'=>$message]);}
 private function actor(int $id):void { $u=User::find($id);abort_unless($u&&$u->is_super_admin&&MarketingPermission::allows($u,MarketingPermission::EDIT),403,'The account owner must approve publishing.'); }
 private function enabled():void{abort_unless(config('marketing.post_queue_enabled',false)&&config('marketing.social_publishing_enabled',false),423,'Publishing is currently unavailable. Your draft is retained.');}
 private function media(int $user,string $key):array { $s=app(MarketingPosts::class);$a=$s->asset($user,$key);if(!$a)$this->invalid('Choose available media before publishing.');$path=$a['kind']==='video'?$s->videoFile($user,$key):$s->imagePath(ProductImage::findOrFail(substr($key,6))->path);if(!$path||!is_file($path))$this->invalid('The selected media is unavailable.');return ['kind'=>$a['kind'],'sha256'=>hash_file('sha256',$path)]; }
 private function options(array $d,string $kind):void {
  foreach($d['targets'] as $id){$old=MarketingPost::find($d['id']);if(($old?->document['outcomes'][$id]['status']??'')==='Published')continue;$c=MarketingChannelConnection::where('merchant_key',app(MarketingPosts::class)->merchant())->findOrFail($id);if(!MarketingPostFormats::supports($c->platform,$d['type'],$kind))$this->invalid('Choose a supported format for each account.');$o=$d['options'][$id]??[];
   if($c->platform==='youtube'&&(!is_string($o['title']??null)||!trim($o['title'])||mb_strlen($o['title'])>100||!in_array($o['privacy']??'', ['private','unlisted','public'],true)||!is_bool($o['made_for_kids']??null)||!is_bool($o['synthetic']??null)))$this->invalid('Review the YouTube title, visibility, audience and content choices.');
   if($c->platform==='tiktok'){if($kind==='image'&&!MarketingPostFormats::photoReady())$this->invalid('Photo publishing is not ready yet. Your draft is retained.');if(($o['terms']??false)!==true||!in_array($o['privacy']??'', ['SELF_ONLY','PUBLIC_TO_EVERYONE','MUTUAL_FOLLOW_FRIENDS','FOLLOWER_OF_CREATOR'],true))$this->invalid('Choose TikTok visibility and confirm its required declaration.');$flags=['allow_comment','commercial','your_brand','branded'];if($kind==='video')$flags=array_merge($flags,['allow_duet','allow_stitch']);foreach($flags as $f)if(!is_bool($o[$f]??null))$this->invalid('Review TikTok interaction and commercial disclosure choices.');if($o['commercial']&&!$o['your_brand']&&!$o['branded'])$this->invalid('Select Your brand or Branded content.');if($o['commercial']&&$o['branded']&&$o['privacy']==='SELF_ONLY')$this->invalid('Branded content cannot be private.');}
  }
 }
 public function approveAutomation(int $user,array $targets,array $options):void {
  $this->actor($user);$this->enabled();$this->options(['id'=>'','targets'=>$targets,'type'=>'Post','options'=>$options],'image');
 }
 public function submit(int $user,array $d,bool $immediate):array {
  $this->actor($user);$this->enabled();if(!$immediate)abort_unless(config('marketing.post_scheduling_enabled',false),423,'Scheduling is not available yet.');if(!$immediate&&!preg_match('/(?:Z|[+-]\d{2}:\d{2})$/D',(string)($d['due']??'')))$this->invalid('Choose an unambiguous date, time and timezone.');$media=isset($d['assets'])?app(MarketingPostContent::class)->snapshot($user,$d):$this->media($user,(string)($d['asset']??''));$this->options($d,$media['kind']);
  return DB::transaction(function()use($user,$d,$immediate,$media){$s=app(MarketingPosts::class);if($immediate)$d['due']=now()->addMinute()->toIso8601String();$saved=$s->write($user,'schedule',$d);if(isset($d['assets']))$media=app(MarketingPostContent::class)->snapshot($user,$saved);$p=MarketingPost::lockForUpdate()->findOrFail($saved['id']);$doc=$p->document;$versions=[];foreach($doc['targets'] as $t)if(($doc['outcomes'][$t]['status']??'')!=='Published')$versions[$t]=MarketingChannelConnection::findOrFail($t)->version;$due=$immediate?CarbonImmutable::now():$p->scheduled_at;
   if($immediate){foreach(array_keys($versions) as $t)$doc['outcomes'][$t]=['status'=>'Queued'];$doc['approvals'][array_key_last($doc['approvals'])]['due']=$due->toIso8601String();$p->status='Queued';$p->scheduled_at=$due;}
   $doc['delivery_phase']=$immediate?'queued':'scheduled';$p->document=$doc;$p->save();$payload=array_intersect_key($s->view($p),array_flip(['id','version','title','copy','targets','copies','asset','assets','media_copies','format','type','tz','options']));$payload['media']=$media;$payload['connections']=$versions;
   $job=MarketingPostDispatch::create(['post_id'=>$p->id,'user_id'=>$user,'revision'=>$p->version,'state'=>$immediate?'queued':'waiting','payload'=>$payload,'due_at'=>$due]);if($immediate)$this->enqueue($job->id);return $s->view($p);
  });
 }
 private function enqueue(string $id):void {abort_unless(config('queue.connections.marketing-posts.driver')==='database'&&config('queue.connections.marketing-posts.connection')===null,500,'Publishing queue configuration is unavailable.');Queue::connection('marketing-posts')->push(new PublishMarketingPost($id),'','marketing-posts');}
 public function sweep():int {
  if(!config('marketing.post_queue_enabled')||!config('marketing.social_publishing_enabled'))return 0;$count=0;
  // Expired workers only enter query/reconciliation. They never return to initial submission.
  MarketingPostDispatch::whereIn('state',['executing','checking'])->where('updated_at','<',now()->subMinutes(15))->pluck('id')->each(fn($id)=>$this->quarantine($id));
  $ids=MarketingPostDispatch::where(fn($q)=>$q->where(fn($q)=>$q->where('state','waiting')->where('due_at','<=',now()))->orWhere(fn($q)=>$q->where('state','waiting_result')->where('next_check_at','<=',now())))->orderBy('due_at')->limit(30)->pluck('id');
  foreach($ids as $id)$count+=DB::transaction(function()use($id){$d=MarketingPostDispatch::lockForUpdate()->find($id);if(!$d||!in_array($d->state,['waiting','waiting_result'],true))return 0;$p=MarketingPost::lockForUpdate()->find($d->post_id);if(!$p){$d->update(['state'=>'cancelled']);return 0;}if($d->state==='waiting'&&($p->status!=='Scheduled'||$p->version!==$d->revision)){ $d->update(['state'=>'superseded']);return 0;}if($d->state==='waiting'&&!config('marketing.post_scheduling_enabled'))return 0;if($d->state==='waiting_result'&&$d->checks>=120){$doc=$p->document;unset($doc['delivery_lock']);$doc['delivery_phase']='attention';foreach($d->payload['connections'] as $t=>$v)if(($doc['outcomes'][$t]['status']??'')!=='Published')$doc['outcomes'][$t]=['status'=>'Needs attention','reason'=>'unknown','code'=>'confirmation_delayed'];$p->update(['document'=>$doc,'status'=>'Needs attention','version'=>$p->version+1]);$d->update(['state'=>'attention','error_code'=>'confirmation_delayed']);return 0;}$d->update(['state'=>$d->state==='waiting'?'queued':'query_queued']);$this->enqueue($d->id);return 1;});return $count;
 }
 public function run(string $id):void {
  $claimed=DB::transaction(function()use($id){$d=MarketingPostDispatch::lockForUpdate()->find($id);if(!$d||!in_array($d->state,['queued','query_queued'],true))return null;$query=$d->state==='query_queued';$p=MarketingPost::lockForUpdate()->find($d->post_id);if(!$p){$d->update(['state'=>'cancelled']);return null;}if(!$query&&($p->version!==$d->revision||!in_array($p->status,['Scheduled','Queued'],true))){$d->update(['state'=>'superseded']);return null;}$d->update(['state'=>$query?'checking':'executing']);if(!$query){$doc=$p->document;$doc['delivery_lock']=$id;$doc['delivery_phase']='publishing';foreach($d->payload['connections'] as $t=>$v)$doc['outcomes'][$t]=['status'=>'Queued'];$p->update(['document'=>$doc,'status'=>'Queued','version'=>$p->version+1]);}return [$d,$p,$query];});if(!$claimed)return;[$d,$p,$query]=$claimed;
  try{$this->actor($d->user_id);$this->enabled();$payload=$d->payload;$kind=$payload['media']['kind'];$multi=MarketingMultiImagePublisher::applies($payload);$adapter=app($multi?MarketingMultiImagePublisher::class:($kind==='video'?MarketingVideoPublisher::class:MarketingImagePublisher::class));
   if($query){$adapter->refresh($d->user_id,$d->post_id);}else{foreach($payload['connections'] as $t=>$version){$c=MarketingChannelConnection::where('merchant_key',app(MarketingPosts::class)->merchant())->find($t);if($c&&$c->version===$version&&$c->expires_at?->isPast()&&ExternalChannelConnections::supports($c->platform)){app(ExternalChannelConnections::class)->refreshForPublishing($c);$c->refresh();}if(!$c||$c->version!==$version)$this->invalid('An account connection changed. Review it before publishing.');}$m=isset($payload['media']['sets'])?app(MarketingPostContent::class)->snapshot($d->user_id,$payload):$this->media($d->user_id,$payload['asset']);if(!hash_equals($payload['media']['sha256'],$m['sha256']))$this->invalid('The selected media changed. Review it before publishing.');$payload['version']=$p->version;$adapter->start($d->user_id,$payload,$d->id);}
   $this->finish($d->id);
  }catch(\Throwable $error){$attempted=DB::table('marketing_post_attempts')->where('post_id',$d->post_id)->where('created_at','>=',$d->created_at)->exists();$this->stop($d->id,$attempted?'delivery_uncertain':($error instanceof ValidationException?'review_required':'publishing_unavailable'),$attempted);}
 }

 public function requestRefresh(int $user,string $post):array {
  $this->actor($user);$this->enabled();return DB::transaction(function()use($user,$post){$p=MarketingPost::where('user_id',$user)->where('merchant_key',app(MarketingPosts::class)->merchant())->findOrFail($post);$d=MarketingPostDispatch::where('post_id',$p->id)->latest()->lockForUpdate()->first();if($d&&in_array($d->state,['waiting_result','attention'],true)&&$this->known($post)){$d->update(['state'=>'query_queued']);$this->enqueue($d->id);}return app(MarketingPosts::class)->view($p);});
 }
 private function known(string $post):bool {return DB::table('marketing_post_attempts')->where('post_id',$post)->whereNotIn('state',['published','failed'])->get()->contains(function($a){$r=json_decode($a->receipt,true)??[];return !empty($r['publish_id'])||!empty($r['session'])||(in_array($a->state,['waiting','multi_waiting'],true)&&(!empty($r['container_id'])||!empty($r['children'])));});}
 private function finish(string $id):void {DB::transaction(function()use($id){$d=MarketingPostDispatch::lockForUpdate()->findOrFail($id);$p=MarketingPost::lockForUpdate()->findOrFail($d->post_id);$doc=$p->document;unset($doc['delivery_lock']);$checking=$p->status==='Needs attention'&&collect($doc['outcomes']??[])->contains(fn($o)=>($o['reason']??'')==='unknown')&&$this->known($p->id);$pending=$p->status==='Publishing'||$checking;$doc['delivery_phase']=$pending?($checking?'checking':'processing'):($p->status==='Published'?'published':'attention');$p->update(['document'=>$doc,'version'=>$p->version+1]);$d->update(['state'=>$pending?'waiting_result':($p->status==='Published'?'completed':'attention'),'checks'=>$d->checks+1,'next_check_at'=>$pending?now()->addSeconds(30):null]);});}
 private function stop(string $id,string $code,bool $unknown):void {DB::transaction(function()use($id,$code,$unknown){$d=MarketingPostDispatch::lockForUpdate()->find($id);if(!$d)return;$p=MarketingPost::lockForUpdate()->find($d->post_id);if(!$p)return;$doc=$p->document;if(collect($d->payload['connections'])->keys()->every(fn($t)=>($doc['outcomes'][$t]['status']??'')==='Published')){unset($doc['delivery_lock']);$doc['delivery_phase']='published';$p->update(['document'=>$doc,'status'=>'Published','version'=>$p->version+1]);$d->update(['state'=>'completed']);return;}unset($doc['delivery_lock']);foreach($d->payload['connections'] as $t=>$v)if(($doc['outcomes'][$t]['status']??'')!=='Published')$doc['outcomes'][$t]=['status'=>'Needs attention','reason'=>$unknown?'unknown':'permission','code'=>$code];$doc['delivery_phase']='attention';$doc['history'][]=['title'=>'Publishing needs attention','text'=>now()->toIso8601String().' · '.$code];$p->update(['document'=>$doc,'status'=>'Needs attention','version'=>$p->version+1]);$d->update(['state'=>$unknown?'waiting_result':'attention','error_code'=>$code,'next_check_at'=>$unknown?now()->addMinutes(2):null]);});}
 public function quarantine(string $id):void {$d=MarketingPostDispatch::find($id);if(!$d)return;if($d->state==='queued')$this->stop($id,'publishing_unavailable',false);elseif(in_array($d->state,['executing','checking','query_queued'],true))$this->stop($id,'delivery_uncertain',true);}
}
